args.command:
python3 - <<'PY'
import os,re,collections
root='internal'
files=[]
for dp,dn,fn in os.walk(root):
  for f in fn:
    if f.endswith('.go'):
      p=os.path.join(dp,f); files.append(p)
# declarations: funcs and methods, name only; count calls by identifier token followed by (
decls=[]
for p in files:
 s=open(p).read()
 # strip comments/strings roughly for declarations only
 for m in re.finditer(r'(?m)^\s*func\s+(?:\([^)]*\)\s*)?([A-Za-z_]\w*)\s*\(',s):
  decls.append((m.group(1),p,m.start()))
counts=collections.defaultdict(set); occurrences=collections.Counter()
for p in files:
 s=open(p).read()
 # remove comments and strings while preserving positions
 s=re.sub(r'//[^\n]*|/\*.*?\*/|"(?:\\.|[^"\\])*"|`[^`]*`|\'(?:\\.|[^\'\\])*\'', '', s, flags=re.S)
 for name,dp,pos in decls:
  # all calls, excluding declaration's own signature by line position rough
  for m in re.finditer(r'(?<![\w.])'+re.escape(name)+r'\s*\(',s):
   # declaration matches could be counted; remove if same file and near declaration
   if p==dp and abs(m.start()-pos)<150: continue
   counts[name].add(p); occurrences[name]+=1
for name in sorted(counts,key=lambda x:(-len(counts[x]),-occurrences[x],x))[:30]:
 print(f'{name}: files={len(counts[name])} occurrences={occurrences[name]} decls={[p for n,p,_ in decls if n==name]}')
PY

